async function refreshCsrf(){ const r=await fetch('/api/csrf',{credentials:'same-origin'}); const j=await r.json(); csrfToken=j.csrf_token; }
async function api(path, method='GET', body=null){
  const opts={method,credentials:'same-origin',headers:{'Accept':'application/json'}};
  if(body!==null){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}
  if(!['GET','HEAD','OPTIONS'].includes(method)) opts.headers['X-CSRF-Token']=csrfToken;
  const response=await fetch(path,opts); let data={};
  try{data=await response.json()}catch(e){data={message:'Server returned an unreadable response.'}}
  if(!response.ok || data.success===false) throw new Error(data.message || `Request failed (${response.status})`);
  return data;
}
function notice(message,type='info'){return `<div class="notice ${type}" role="status">${esc(message)}</div>`}

