 const tenantNav=[['dashboard','▦','Overview'],['portal-builder','▣','Captive portal'],['customers','♙','Customers'],['packages','◈','Services & packages'],['vouchers','▤','Vouchers'],['invoices','▧','Invoices'],['payments','⇄','Payments'],['routers','⌁','Routers'],['agents','♧','Agents'],['billing','▧','RIS plan'],['settings','⚙','Settings']];
 const roleAccess={dashboard:['owner','admin','finance','network_admin','support','agent'],customers:['owner','admin','finance','support','network_admin'],packages:['owner','admin','finance','network_admin','support','agent'],vouchers:['owner','admin','network_admin','support','agent'],invoices:['owner','admin','finance','support'],payments:['owner','admin','finance','support'],routers:['owner','admin','network_admin','support'],agents:['owner','admin','finance','agent'],billing:['owner','admin','finance'],settings:['owner','admin','network_admin'],'portal-builder':['owner','admin','network_admin']};
 const nav=isPlatform?[['dashboard','▦','Overview'],['tenants','◫','ISP workspaces'],['customers','♙','All customers'],['billing','▧','SaaS billing'],['account','◉','My account']]:isCustomer?[['portal','⌂','My internet'],['account','◉','My account']]:tenantNav.filter(([id])=>(roleAccess[id]||[]).includes(currentUser.role)).concat([['account','◉','My account']]);
 const tenantLabel=isPlatform?'Platform control':isCustomer?'Customer account':'ISP workspace';
