 const canManage=['owner','admin','finance'].includes(currentUser.role);
 const cards=d.items.map(x=>`<div class="package-card"><h3>${esc(x.name)}</h3><span class="badge ${x.active?'success':'danger'}">${x.active?'Available':'Inactive'}</span><div class="price">${money(x.price_minor)} <small>/ ${x.validity_hours} hours</small></div><div class="package-meta"><span>▣ ${x.data_limit_mb?x.data_limit_mb+' MB':'Unlimited data'}</span><span>↓ ${x.speed_down_kbps?x.speed_down_kbps+' Kbps':'Default speed'}</span><span>↑ ${x.speed_up_kbps?x.speed_up_kbps+' Kbps':'Default speed'}</span><span>Devices: ${x.device_limit}</span></div>${canManage?`<button class="btn btn-light btn-block" data-action="toggle-package" data-id="${x.id}" data-active="${x.active?0:1}">${x.active?'Deactivate':'Activate'}</button>`:''}</div>`);
 el.innerHTML=pageHead('Internet packages','Configure the hotspot and PPPoE products available to this ISP.')+`${canManage?`<div class="panel"><div class="panel-head"><h3>Create package</h3></div><div class="panel-body"><form id="addPackageForm" class="form-grid"><div class="field"><label>Package name</label><input name="name" placeholder="Home 10 Mbps" required></div><div class="field"><label>Service type</label><select name="service_type"><option>hotspot</option><option>pppoe</option></select></div><div class="field"><label>Price (UGX)</label><input name="price" type="number" min="0" required></div><div class="field"><label>Validity (hours)</label><input name="validity_hours" type="number" min="1" value="24" required></div><div class="field"><label>Data limit (MB, 0 = unlimited)</label><input name="data_limit_mb" type="number" min="0" value="0"></div><div class="field"><label>Download speed (Kbps)</label><input name="speed_down_kbps" type="number" min="0" value="0"></div><div class="field"><label>Upload speed (Kbps)</label><input name="speed_up_kbps" type="number" min="0" value="0"></div><div class="field"><label>Device limit</label><input name="device_limit" type="number" min="1" value="1"></div><div class="form-actions"><button class="btn btn-primary">Save package</button></div></form></div></div>`:''}<div class="package-grid">${cards.join('')||'<div class="panel"><div class="panel-body">No packages configured.</div></div>'}</div>`;
