async function loadSettings(el){const canManage=['owner','admin'].includes(currentUser.role);const [d,i,p]=await Promise.all([api('/api/tenant/settings'),api('/api/integrations/status'),api('/api/tenant/integrations')]);const t=d.tenant;const ps=p.providers||{};el.innerHTML=pageHead('Workspace settings','Manage branding and configure payment credentials securely for this ISP.')+`<div class="split"><div class="panel"><div class="panel-head"><h3>Branding and identity</h3></div><div class="panel-body">${canManage?`<form id="settingsForm"><div class="field"><label>ISP business name</label><input name="name" value="${esc(t.name)}"></div><div class="field"><label>Customer-facing brand name</label><input name="brand_name" value="${esc(t.brand_name||t.name)}"></div><div class="grid2"><div class="field"><label>Primary brand colour</label><input name="brand_primary" value="${esc(t.brand_primary||'#087bd1')}"></div><div class="field"><label>Custom domain (record only)</label><input name="custom_domain" value="${esc(t.custom_domain||'')}" placeholder="portal.example.com"></div></div><button class="btn btn-primary">Save workspace settings</button></form>`:`<p class="footer-note">Your role can inspect integration health. Business identity and branding changes are restricted to the ISP owner or administrator.</p>`}<p class="footer-note">Custom domain is recorded only. DNS validation and automatic TLS still require a production domain setup.</p></div></div><div class="panel"><div class="panel-head"><h3>Integration health</h3></div><div class="panel-body"><div class="stat-top">Gmail SMTP <b>${statusBadge(i.integrations.gmail_smtp?'Configured':'Missing')}</b></div><hr style="border:0;border-top:1px solid var(--line);margin:13px 0"><div class="stat-top">Africa's Talking SMS <b>${statusBadge(i.integrations.africas_talking_sms?'Configured':'Missing')}</b></div><hr style="border:0;border-top:1px solid var(--line);margin:13px 0"><div class="stat-top">Flutterwave <b>${statusBadge(ps.flutterwave?.configured?'Credentials saved':'Not configured')}</b></div><hr style="border:0;border-top:1px solid var(--line);margin:13px 0"><div class="stat-top">MTN MoMo <b>${statusBadge(ps.mtn_momo?.configured?'Credentials saved':'Not configured')}</b></div><hr style="border:0;border-top:1px solid var(--line);margin:13px 0"><div class="stat-top">Airtel Money <b>${statusBadge(ps.airtel_money?.configured?'Credentials saved':'Not configured')}</b></div><p class="footer-note">Credentials are encrypted at rest. A saved key does not mean the provider has completed a live transaction test.</p></div></div></div><div class="grid2"><div class="panel"><div class="panel-head"><h3>Flutterwave checkout</h3></div><div class="panel-body">${canManage?`<form id="flutterwaveSettingsForm"><div class="field"><label>Secret key</label><input name="secret_key" type="password" autocomplete="new-password" placeholder="Leave blank to keep existing"></div><div class="field"><label>Webhook secret hash</label><input name="webhook_secret" type="password" autocomplete="new-password" placeholder="Leave blank to keep existing"></div><div class="field"><label>Environment</label><select name="environment"><option value="test">Test / sandbox</option><option value="live">Live</option></select></div><button class="btn btn-primary">Save Flutterwave credentials</button></form>`:''}<button class="btn btn-light" data-action="test-provider" data-provider="flutterwave">Test credentials</button></div></div><div class="panel"><div class="panel-head"><h3>MTN MoMo Collections</h3></div><div class="panel-body">${canManage?`<form id="mtnSettingsForm"><div class="field"><label>API user UUID</label><input name="api_user" autocomplete="off"></div><div class="field"><label>API key</label><input name="api_key" type="password" autocomplete="new-password"></div><div class="field"><label>Collections subscription key</label><input name="subscription_key" type="password" autocomplete="new-password"></div><div class="grid2"><div class="field"><label>Environment</label><select name="environment"><option value="sandbox">Sandbox</option><option value="production">Production</option></select></div><div class="field"><label>Target environment</label><input name="target_environment" value="mtnuganda"></div></div><button class="btn btn-primary">Save MTN credentials</button></form>`:''}<button class="btn btn-light" data-action="test-provider" data-provider="mtn_momo">Test credentials</button></div></div></div><div class="panel"><div class="panel-head"><h3>Airtel Money</h3></div><div class="panel-body">Airtel application credentials can be recorded here in a future adapter release. The current build intentionally does not initiate or mark Airtel collections as paid until its country-specific application contract and callback verification are confirmed with Airtel's developer portal.</div></div><div class="panel"><div class="panel-body"><b>Workspace status:</b> ${statusBadge(t.status)} &nbsp; <b>Plan:</b> ${esc(t.plan)} &nbsp; <b>Trial ends:</b> ${fmtDate(t.trial_ends_at)}</div></div>`;}
async function loadAccount(el){el.innerHTML=pageHead('My account','Update your sign-in password. Your current session stays active.')+`<div class="panel"><div class="panel-head"><h3>Account details</h3></div><div class="panel-body"><p><b>${esc(currentUser.full_name)}</b><br><span class="footer-note">${esc(currentUser.email)} · ${esc(currentUser.role.replace('_',' '))}</span></p><form id="changePasswordForm" style="max-width:520px"><div class="field"><label>Current password</label><input name="current_password" type="password" required autocomplete="current-password"></div><div class="field"><label>New password</label><input name="new_password" type="password" minlength="12" required autocomplete="new-password"><small>Use at least 12 characters. Other active sessions will be signed out.</small></div><button class="btn btn-primary">Update password</button></form></div></div>`;}
