async function loadPortal(el){const [p,s,n]=await Promise.all([api('/api/portal/packages'),api('/api/portal/summary'),api('/api/portal/network-credentials')]);const active=s.subscriptions.filter(x=>x.status==='active'&&new Date(x.expires_at)>new Date());const providers=p.payment_providers||{};el.innerHTML=pageHead('Your internet account','Buy internet packages, check usage records and manage your access credentials.')+`<div class="stats">${statCard('Customer',esc(s.customer.name),'♙',esc(s.customer.phone))}${statCard('Active subscriptions',active.length,'◈')}${statCard('Payment records',s.payments.length,'⇄')}${statCard('Workspace',esc(currentUser.tenant?.name||''),'⌂')}</div><div class="panel"><div class="panel-head"><h3>Available packages</h3></div><div class="panel-body"><div class="package-grid">${p.items.map(x=>`<div class="package-card"><h3>${esc(x.name)}</h3><div class="price">${money(x.price_minor)} <small>/ ${x.validity_hours} hours</small></div><div class="package-meta"><span>${x.data_limit_mb?x.data_limit_mb+' MB data':'Unlimited data'}</span><span>Download: ${x.speed_down_kbps||'default'} Kbps</span><span>Upload: ${x.speed_up_kbps||'default'} Kbps</span></div>${providers.flutterwave?.configured?`<button class="btn btn-primary btn-block" data-action="purchase" data-provider="flutterwave" data-id="${x.id}">Pay with Flutterwave</button>`:''}${providers.mtn_momo?.configured?`<button class="btn btn-light btn-block" style="margin-top:7px" data-action="purchase" data-provider="mtn_momo" data-id="${x.id}">Pay with MTN MoMo</button>`:''}${!providers.flutterwave?.configured&&!providers.mtn_momo?.configured?`<button class="btn btn-primary btn-block" data-action="purchase" data-provider="demo" data-id="${x.id}">Test purchase (demo)</button>`:''}</div>`).join('')||'<p>No packages are currently available from your ISP.</p>'}</div></div></div><div class="panel"><div class="panel-head"><h3>Hotspot / PPPoE login</h3><button class="btn btn-light" data-action="refresh-network">Refresh credentials</button></div><div class="panel-body">${n.account?`<div class="grid2"><div><small class="footer-note">Username</small><p><b class="mono">${esc(n.account.username)}</b></p></div><div><small class="footer-note">Password</small><p><b class="mono">${esc(n.account.password)}</b></p></div></div><p class="footer-note">Provisioning status: ${statusBadge(n.account.provision_status)}. Keep these credentials private. Internet access is provided only after the ISP's MikroTik/RADIUS infrastructure has been connected.</p>`:`<p>${esc(n.message||'Network access credentials will appear after a confirmed purchase.')}</p>`}</div></div><div class="split"><div class="panel"><div class="panel-head"><h3>My subscriptions</h3></div>${table(['Package','Status','Start','Expires'],s.subscriptions.map(x=>`<tr><td><b>${esc(x.package_name)}</b></td><td>${statusBadge(new Date(x.expires_at)>new Date()?x.status:'expired')}</td><td>${fmtDate(x.starts_at)}</td><td>${fmtDate(x.expires_at)}</td></tr>`))}</div><div class="panel"><div class="panel-head"><h3>My payments</h3></div>${table(['Reference','Amount','Status'],s.payments.map(x=>`<tr><td class="mono">${esc(x.reference)}</td><td>${money(x.amount_minor)}</td><td>${statusBadge(x.status)}</td></tr>`))}</div></div>`;}

async function loadBilling(el){
 if(currentUser.role==='platform_admin'){
  const d=await api('/api/platform/billing');const s=d.summary;
  el.innerHTML=pageHead('RIS SaaS billing','Manage recurring software subscriptions billed to ISP businesses.')+`<div class="stats">${statCard('Subscription invoices',s.invoice_count,'▧')}${statCard('Collected',money(s.collected),'↗')}${statCard('Outstanding',money(s.outstanding),'◷')}${statCard('Available plans',d.plans.length,'◈')}</div><div class="panel"><div class="panel-head"><h3>Platform billing ledger</h3></div>${table(['ISP','Workspace','Plan','Amount','Status','Due date','Created'],d.invoices.map(x=>`<tr><td><b>${esc(x.tenant_name)}</b></td><td>${esc(x.tenant_slug)}</td><td>${esc(x.plan_code)}</td><td>${money(x.amount)}</td><td>${statusBadge(x.status)}</td><td>${fmtDate(x.due_at)}</td><td>${fmtDate(x.created_at)}</td></tr>`))}</div>`;
  return;
 }
 const [d,u]=await Promise.all([api('/api/tenant/billing'),api('/api/tenant/usage')]);
 const sub=d.subscription;const usage=u.usage||{};const limits=u.limits||{};
 const customers=`${Number(usage.customers||0).toLocaleString()} / ${Number(limits.customers||0).toLocaleString()}`;
 const routers=`${Number(usage.routers||0).toLocaleString()} / ${Number(limits.routers||0).toLocaleString()}`;
 const featureText=Object.entries(u.features||{}).filter(([,enabled])=>enabled).map(([name])=>name.replaceAll('_',' ')).join(' · ')||'Core billing';
 el.innerHTML=pageHead('RIS subscription','Manage the software plan and subscription billing for this ISP. This is separate from money collected from your customers.')+`<div class="stats">${statCard('Current plan',esc(sub?.plan_name||'Starter'),'◈')}${statCard('Subscription status',esc(sub?.status||'trial'),'✓')}${statCard('Customer allowance',customers,'♙')}${statCard('Router allowance',routers,'⌁')}</div><div class="panel"><div class="panel-head"><h3>Plan usage and entitlements</h3></div><div class="panel-body"><div class="stat-top"><span>Next billing date</span><b>${fmtDate(sub?.next_invoice_at)}</b></div><p class="footer-note">Enabled features: ${esc(featureText)}. ${Number(usage.agents||0).toLocaleString()} registered agents.</p></div></div><div class="panel"><div class="panel-head"><h3>Available RIS plans</h3></div><div class="panel-body"><form id="chooseSaasPlanForm" class="form-grid"><div class="field"><label>Plan</label><select name="plan_code">${d.plans.map(x=>`<option value="${x.code}" ${sub?.plan_code===x.code?'selected':''}>${esc(x.name)} · ${money(x.monthly_price)} / month · ${Number(x.max_customers).toLocaleString()} customers · ${x.max_routers} routers</option>`).join('')}</select></div><div class="field"><label>Billing cycle</label><select name="billing_cycle"><option value="monthly">Monthly</option><option value="annual">Annual</option></select></div><div class="form-actions"><button class="btn btn-primary">Create plan invoice</button></div></form></div></div><div class="panel"><div class="panel-head"><h3>Subscription invoices</h3></div>${table(['Invoice','Plan','Amount','Status','Due date','Action'],d.invoices.map(x=>`<tr><td class="mono">${esc(x.id)}</td><td>${esc(x.plan_code||'')}</td><td>${money(x.amount)}</td><td>${statusBadge(x.status)}</td><td>${fmtDate(x.due_at)}</td><td>${x.status!=='paid'?`<button class="btn btn-light" data-action="pay-saas-invoice" data-id="${x.id}">${d.payment_mode==='demo'?'Confirm demo payment':'Pay invoice'}</button>`:'Paid'}</td></tr>`))}</div>`;
}

app.addEventListener('click',async e=>{
 const opener=e.target.closest('[data-open-auth]');if(opener){authMode=opener.dataset.openAuth;activeChallenge=null;otpPurpose='';lastRegistration=null;renderAuth();window.scrollTo({top:0,behavior:'instant'});return}
 const home=e.target.closest('[data-home]');if(home){e.preventDefault();currentUser=null;authMode='login';activeChallenge=null;otpPurpose='';lastRegistration=null;renderLanding();return}
 const auth=e.target.closest('[data-auth]');if(auth){authMode=auth.dataset.auth;activeChallenge=null;lastRegistration=null;renderAuth();return}
 const cm=e.target.closest('[data-customer-mode]');if(cm){lastRegistration={kind:cm.dataset.customerMode};renderAuth();return}
 const view=e.target.closest('[data-view]');if(view){setView(view.dataset.view);document.getElementById('sidebar')?.classList.remove('open');return}
 const action=e.target.closest('[data-action]');if(!action)return;
 try{
  if(action.dataset.action==='cancel-otp'){activeChallenge=null;otpPurpose='';renderAuth();return}
  if(action.dataset.action==='logout'){await api('/api/auth/logout','POST',{});currentUser=null;activeChallenge=null;await refreshCsrf();authMode='login';renderLanding();return}
  if(action.dataset.action==='hotspot-buy'){const card=action.closest('.hotspot-card');const name=document.querySelector('.public-hotspot')?.dataset.registration==='no'?'Guest Customer':prompt('Enter your name for this trial purchase:');if(!name)return;const d=await api('/api/public/portal/'+encodeURIComponent(pathPortalSlug)+'/purchase','POST',{package_id:action.dataset.id,name});if(!confirm('TRIAL CHECKOUT ONLY\n'+d.currency+' '+Number(d.amount).toLocaleString('en-UG')+'\nNo money will be collected. Simulate successful payment?'))return;const result=await api('/api/public/portal/'+encodeURIComponent(pathPortalSlug)+'/purchase/'+d.payment_id+'/confirm','POST',{demo_token:d.demo_token});document.getElementById('hotspot-result').innerHTML=notice(result.message+' Access expires: '+fmtDate(result.expires_at),'success');return}
  if(action.dataset.action==='preview-portal'){window.open(action.dataset.url,'_blank','noopener');return}
  if(action.dataset.action==='copy-portal-url'){await navigator.clipboard.writeText(action.dataset.url);alert('Portal link copied.');return}
  if(action.dataset.action==='toggle-menu'){document.getElementById('sidebar')?.classList.toggle('open');return}
  if(action.dataset.action==='public-menu'){document.querySelector('.site-header')?.classList.toggle('menu-open');return}
  if(action.dataset.action==='toggle-package'){await api('/api/packages/'+action.dataset.id,'PATCH',{active:Number(action.dataset.active)});await loadView('packages');return}
  if(action.dataset.action==='tenant-status'){await api('/api/platform/tenants/'+action.dataset.id+'/status','PATCH',{status:action.dataset.status});await loadView('tenants');return}
  if(action.dataset.action==='customer-edit'){const name=prompt('Customer full name',action.dataset.name||'');if(name===null)return;const email=prompt('Customer email',action.dataset.email||'');if(email===null)return;const phone=prompt('Customer phone',action.dataset.phone||'');if(phone===null)return;const address=prompt('Customer address',action.dataset.address||'');if(address===null)return;await api('/api/customers/'+action.dataset.id,'PATCH',{name,email,phone,address});await loadView('customers');return}
  if(action.dataset.action==='customer-status'){await api('/api/customers/'+action.dataset.id,'PATCH',{status:action.dataset.status});await loadView('customers');return}
  if(action.dataset.action==='customer-archive'){if(!confirm('Archive this customer? Their billing history will be retained.'))return;await api('/api/customers/'+action.dataset.id,'DELETE',{});await loadView('customers');return}
  if(action.dataset.action==='customer-restore'){await api('/api/customers/'+action.dataset.id+'/restore','POST',{});await loadView('customers');return}
  if(action.dataset.action==='search-customers'){customerQuery=document.getElementById('customerSearchInput')?.value||'';await loadView('customers');return}
  if(action.dataset.action==='show-archived'){const d=await api('/api/customers?include_archived=true&status=archived');const content=document.getElementById('viewContent');content.innerHTML=pageHead('Archived customers','Archived records are retained for financial and audit history.')+`<div class="panel"><div class="panel-head"><h3>Archived (${d.items.length})</h3><button class="btn btn-light" data-view="customers">Back to active customers</button></div>${table(['Customer','Email','Phone','Service','Status','Created','Action'],d.items.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td>${esc(x.phone)}</td><td>${esc(x.service_type)}</td><td>${statusBadge(x.status)}</td><td>${fmtDate(x.created_at)}</td><td><button class="btn btn-light btn-small" data-action="customer-restore" data-id="${esc(x.id)}">Restore as pending</button></td></tr>`))}</div>`;return}
  if(action.dataset.action==='platform-customer-search'){platformCustomerTenant=document.getElementById('platformCustomerTenant')?.value||'';platformCustomerQuery=document.getElementById('platformCustomerSearch')?.value||'';await loadView('customers');return}
  if(action.dataset.action==='platform-customer-archive-filter'){platformCustomerIncludeArchived=!platformCustomerIncludeArchived;await loadView('customers');return}
  if(action.dataset.action==='platform-customer-status'){await api('/api/platform/customers/'+action.dataset.id,'PATCH',{status:action.dataset.status});await loadView('customers');return}
  if(action.dataset.action==='purchase'){const d=await api('/api/portal/purchase','POST',{package_id:action.dataset.id});if(action.dataset.provider==='demo'){if(!confirm('DEVELOPMENT SIMULATION ONLY: No real money is collected. Continue?'))return;const result=await api('/api/payments/'+d.payment_id+'/demo-confirm','POST',{});alert(result.message);await loadView('portal');return}const checkout=await api('/api/payments/'+d.payment_id+'/checkout','POST',{provider:action.dataset.provider});if(checkout.checkout_url){location.href=checkout.checkout_url}else{alert(checkout.message+' You can refresh the portal after approving the prompt.');await loadView('portal')}return}
  if(action.dataset.action==='router-test'){const r=await api('/api/routers/'+action.dataset.id+'/test','POST',{});alert(r.message||`${r.identity} · RouterOS ${r.version}`);await loadView('routers');return}
  if(action.dataset.action==='router-inspect'){const r=await api('/api/routers/'+action.dataset.id+'/status');const target=document.getElementById('viewContent');const rows=(r.sessions||[]).map(x=>`<tr><td>${esc(x.service)}</td><td><b>${esc(x.name)}</b></td><td class=\"mono\">${esc(x.address)}</td><td>${esc(x.uptime)}</td><td class=\"mono\">${esc(x.caller_id)}</td></tr>`);target.insertAdjacentHTML('afterbegin',`<div class=\"panel\"><div class=\"panel-head\"><h3>Live router status · ${esc(r.identity)}</h3><span class=\"badge success\">ONLINE</span></div><div class=\"panel-body\"><div class=\"stats\"><div class=\"stat\"><span>RouterOS</span><strong>${esc(r.version)}</strong></div><div class=\"stat\"><span>Uptime</span><strong>${esc(r.uptime)}</strong></div><div class=\"stat\"><span>CPU load</span><strong>${esc(r.cpu_load??'N/A')}%</strong></div><div class=\"stat\"><span>Hotspot / PPPoE</span><strong>${r.hotspot_sessions} / ${r.pppoe_sessions}</strong></div></div><p class=\"footer-note\">Read-only snapshot. No router settings or subscriber sessions were changed.</p>${table(['Service','Username','IP address','Uptime','Caller ID'],rows,'No active Hotspot or PPPoE sessions.')}</div></div>`);return}
  if(action.dataset.action==='router-radius'){const r=await api('/api/routers/'+action.dataset.id+'/configure-radius','POST',{});alert(r.message);await loadView('routers');return}
  if(action.dataset.action==='test-provider'){const r=await api('/api/tenant/integrations/'+action.dataset.provider+'/test','POST',{});alert(r.message);return}
  if(action.dataset.action==='refresh-network'){await loadView('portal');return}
  if(action.dataset.action==='pay-saas-invoice'){const billing=await api('/api/tenant/billing');if(billing.payment_mode==='demo'){if(!confirm('DEVELOPMENT SIMULATION ONLY: this will not collect real money. Confirm the local RIS plan payment?'))return;const paid=await api('/api/tenant/billing/invoices/'+action.dataset.id+'/demo-confirm','POST',{});alert(paid.message);await loadView('billing');return}const d=await api('/api/tenant/billing/invoices/'+action.dataset.id+'/checkout','POST',{});location.href=d.checkout_url;return}
 }catch(err){alert(err.message)}
});
app.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target;const fd=new FormData(form);const val=Object.fromEntries(fd.entries());const submit=form.querySelector('button[type="submit"],button:not([type])');if(submit){submit.disabled=true;submit.dataset.old=submit.textContent;submit.textContent='Please wait…'}
 try{
  if(form.id==='loginForm'){
   const d=await api('/api/auth/login','POST',val);currentUser=d.user;await refreshCsrf();const me=await api('/api/me');currentUser=me.user;currentView=currentUser.role==='customer'?'portal':'dashboard';renderWorkspace();return;
  }
  if(form.id==='ispRegisterForm'){
   const d=await api('/api/auth/register/isp/start','POST',val);activeChallenge=d.challenge_id;otpPurpose='isp';renderAuth(d.development_only_codes?`Local test codes: EMAIL ${d.development_only_codes.email} · SMS ${d.development_only_codes.sms}`:d.message,d.development_only_codes?'warn':'success');return;
  }
  if(form.id==='customerRegisterForm'){
   const d=await api('/api/auth/register/customer/start','POST',val);activeChallenge=d.challenge_id;otpPurpose='customer';lastRegistration={kind:'register'};renderAuth(d.development_only_codes?`Local test codes: EMAIL ${d.development_only_codes.email} · SMS ${d.development_only_codes.sms}`:d.message,d.development_only_codes?'warn':'success');return;
  }
  if(form.id==='otpForm'){
   const endpoint=otpPurpose==='isp'?'/api/auth/register/isp/verify':'/api/auth/register/customer/verify';const d=await api(endpoint,'POST',{challenge_id:activeChallenge,...val});activeChallenge=null;otpPurpose='';await refreshCsrf();const me=await api('/api/me');currentUser=me.user;currentView=currentUser.role==='customer'?'portal':'dashboard';renderWorkspace();return;
  }
  if(form.id==='publicVoucherForm'){const result=await api('/api/public/portal/'+encodeURIComponent(pathPortalSlug)+'/redeem-voucher','POST',val);document.getElementById('hotspot-result').innerHTML=notice(result.message+' Package: '+result.package+'. Expires: '+fmtDate(result.expires_at),'success');form.reset();return}
  if(form.id==='portalDesignerForm'){const config={headline:val.headline,welcome_message:val.welcome_message,primary_color:val.primary_color,background_color:val.background_color,footer_text:val.footer_text,show_packages:fd.has('show_packages'),show_voucher:fd.has('show_voucher'),show_registration:fd.has('show_registration')};const result=await api('/api/tenant/captive-portal','PUT',{config,enabled:fd.has('enabled')});alert(result.message);await loadView('portal-builder');return}
  if(form.id==='platformAddCustomerForm'){const created=await api('/api/platform/customers','POST',val);alert(created.message);platformCustomerTenant=val.tenant_id;await loadView('customers');return}
  const endpointMap={changePasswordForm:['/api/auth/change-password','POST'],addCustomerForm:['/api/customers','POST'],addPackageForm:['/api/packages','POST'],voucherForm:['/api/vouchers/generate','POST'],invoiceForm:['/api/invoices','POST'],routerForm:['/api/routers','POST'],agentForm:['/api/agents','POST'],settingsForm:['/api/tenant/settings','PATCH'],chooseSaasPlanForm:['/api/tenant/billing/choose-plan','POST']};
  if(form.id==='flutterwaveSettingsForm'){const {secret_key,webhook_secret,environment}=val;await api('/api/tenant/integrations/flutterwave','PUT',{secrets:{secret_key,webhook_secret},config:{environment}});await loadView('settings');return}
  if(form.id==='mtnSettingsForm'){const {api_user,api_key,subscription_key,environment,target_environment}=val;await api('/api/tenant/integrations/mtn_momo','PUT',{secrets:{api_user,api_key,subscription_key},config:{environment,target_environment}});await loadView('settings');return}
  if(form.id==='routerCredentialsForm'){const {router_id,...credentials}=val;await api('/api/routers/'+router_id+'/credentials','PUT',credentials);alert('Encrypted router credentials saved.');await loadView('routers');return}
  if(endpointMap[form.id]){const [url,method]=endpointMap[form.id];const result=await api(url,method,val);if(form.id==='chooseSaasPlanForm'){alert(result.message);await loadView('billing');return}await loadView(currentView);return}
 }catch(err){if(currentUser){const content=document.getElementById('viewContent');if(content)content.insertAdjacentHTML('afterbegin',notice(err.message,'error'));}else{renderAuth(err.message,'error')}}
 finally{if(submit&&document.body.contains(submit)){submit.disabled=false;submit.textContent=submit.dataset.old||'Submit'}}
});

window.addEventListener('popstate',()=>{if(currentUser){renderWorkspace();return}if(location.pathname.startsWith('/portal')){authMode='customer';renderAuth()}else{renderLanding()}});

async function renderPublicPortal(){
 try{
  await refreshCsrf(); const d=await api('/api/public/portal/'+encodeURIComponent(pathPortalSlug)); const t=d.tenant,c=d.config||{};
  document.title=(t.brand_name||t.name)+' | Internet access';
  const packages=d.packages||[];
  app.innerHTML=`<main class="public-hotspot" data-registration="${c.show_registration!==false?'yes':'no'}" style="--portal-primary:${esc(c.primary_color||'#087bd1')};--portal-bg:${esc(c.background_color||'#071a2e')}"><section class="hotspot-card"><div class="hotspot-brand">${logo('hotspot-logo')}<span>${esc(t.brand_name||t.name)}</span></div><div class="hotspot-label">SECURE INTERNET ACCESS</div><h1>${esc(c.headline||'Welcome to '+(t.brand_name||t.name))}</h1><p class="hotspot-welcome">${esc(c.welcome_message||'Choose an internet package or enter your voucher to get connected.')}</p>${d.trial_mode?'<div class="trial-ribbon">TRIAL MODE · SIMULATED CHECKOUT · NO REAL MONEY</div>':''}${c.show_packages!==false?`<h2>Available packages</h2><div class="hotspot-packages">${packages.map(p=>`<article class="hotspot-package"><div><b>${esc(p.name)}</b><small>${p.validity_hours} hours · ${p.data_limit_mb?esc(p.data_limit_mb)+' MB':'Unlimited data'}</small></div><strong>${esc(p.currency)} ${Number(p.price_minor).toLocaleString('en-UG')}</strong>${d.trial_mode?`<button class="btn btn-primary" data-action="hotspot-buy" data-id="${esc(p.id)}">Test purchase</button>`:`<span class="hotspot-live-note">Contact this ISP to purchase access</span>`}</article>`).join('')||'<p>No active hotspot packages are available yet.</p>'}</div>`:''}${c.show_voucher!==false?`<div class="hotspot-voucher"><h2>Have a voucher?</h2>${d.trial_mode?`<form id="publicVoucherForm">${c.show_registration!==false?'<input name="name" placeholder="Your name (optional)" maxlength="120">':''}<input name="code" placeholder="Enter voucher code" required autocomplete="off"><button class="btn btn-outline">Redeem voucher</button></form>`:`<p class="hotspot-live-note">Voucher access will be available when this ISP enables live network authentication.</p>`}</div>`:''}<div id="hotspot-result" aria-live="polite"></div><footer>${esc(c.footer_text||'Powered by RIS')}</footer></section></main>`;
 }catch(e){app.innerHTML=`<main class="public-hotspot"><section class="hotspot-card"><h1>Portal unavailable</h1><p>${esc(e.message)}</p><a class="btn btn-outline" href="/">Visit RIS</a></section></main>`}
}

(async function init(){
 if(pathPortalSlug){await renderPublicPortal();return}
 if(isSuperAdminPath){
  await refreshCsrf();
  try{const me=await api('/api/me');if(me.user.role==='platform_admin'){currentUser=me.user;currentView='dashboard';renderWorkspace();return}}catch(e){}
  authMode='login';renderAuth('This page is restricted to the RIS platform administrator.','error');return;
 }
 try{await refreshCsrf();const me=await api('/api/me');currentUser=me.user;currentView=currentUser.role==='customer'?'portal':'dashboard';renderWorkspace();const q=new URLSearchParams(location.search);if(currentUser.role==='customer'&&q.get('tx_ref')&&q.get('transaction_id')){try{const result=await api('/api/payments/verify-return','POST',{tx_ref:q.get('tx_ref'),transaction_id:q.get('transaction_id')});alert(result.message)}catch(err){alert('Payment return received, but verification did not complete: '+err.message)}history.replaceState({},'', '/portal/'+(currentUser.tenant?.slug||''));await loadView('portal')}}
 catch(e){if(location.pathname.startsWith('/portal')){authMode='customer';renderAuth()}else{renderLanding()}}
})();
